'use client';

import { useState } from 'react';
import type { PostMortem } from '@/lib/types';
import { Badge, SeverityBadge } from './ui';
import { IconCheck, IconDoc, IconDownload, IconRefresh } from './icons';
import { toast } from './Toaster';
import { dt } from '@/lib/format';

export function postMortemToMarkdown(pm: PostMortem): string {
  return `# ${pm.title}

**Generated by:** CodePulse · ${pm.generatedBy === 'llm' ? 'LLM + PulseReasoner retrieval' : 'PulseReasoner v1'}
**Generated at:** ${dt(pm.generatedAt)}
**Severity:** ${pm.severity.toUpperCase()}   **Status:** ${pm.status}
**Linked incident:** ${pm.incidentId ?? '—'}   **Analysis:** ${pm.analysisId ?? '—'}

## 1. Summary
${pm.summary}

## 2. Impact
${pm.impact}

### Metrics
| Metric | Value |
| --- | --- |
| MTTR | ${pm.metrics.mttr} |
| Blast radius | ${pm.metrics.blastRadius} |
| Error-budget burn | ${pm.metrics.errorBudgetBurn} |
| Customer impact | ${pm.metrics.customerImpact} |

## 3. Timeline
${pm.timeline.map((t) => `- \`${t.at.slice(11, 19)}Z\` **${t.label}** — ${t.detail}`).join('\n')}

## 4. Root cause
${pm.rootCause}

## 5. Resolution
${pm.resolution}

## 6. Preventive actions
${pm.preventiveActions.map((p, i) => `${i + 1}. ${p}`).join('\n')}

## 7. Action items
| # | Task | Owner | Due | Priority |
| --- | --- | --- | --- | --- |
${pm.actionItems.map((a, i) => `| ${i + 1} | ${a.task} | ${a.owner} | ${a.due} | ${a.priority} |`).join('\n')}

## 8. Lessons learned
${pm.lessonsLearned.map((l) => `- ${l}`).join('\n')}

---
*Blameless post-mortem generated by CodePulse — AI Incident Memory & Root-Cause Intelligence.*
*"Your Engineering Team Never Forgets."*
`;
}

export function downloadMarkdown(pm: PostMortem) {
  const blob = new Blob([postMortemToMarkdown(pm)], { type: 'text/markdown;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `${pm.id}-postmortem.md`;
  a.click();
  URL.revokeObjectURL(url);
  toast('Post-mortem exported', `${pm.id}.md downloaded.`, 'ok');
}

/* ── Collapsible section ─────────────────────────────────────────────────── */
function ReportSection({
  num,
  title,
  children,
  defaultOpen = false,
}: {
  num: number;
  title: string;
  children: React.ReactNode;
  defaultOpen?: boolean;
}) {
  const [open, setOpen] = useState(defaultOpen);
  return (
    <div className="report-section">
      <button type="button" className="report-section-toggle" onClick={() => setOpen((v) => !v)}>
        <span className="report-section-num">{num}</span>
        <span className="report-section-title">{title}</span>
        <span className={`report-section-chevron ${open ? 'open' : ''}`}>▾</span>
      </button>
      {open ? <div className="report-section-body">{children}</div> : null}
    </div>
  );
}

export function PostMortemDoc({
  postMortem,
  compact = false,
  onRegenerate,
}: {
  postMortem: PostMortem;
  compact?: boolean;
  onRegenerate?: () => Promise<void> | void;
}) {
  const [busy, setBusy] = useState(false);

  return (
    <article className="panel">
      <header className="panel-head" style={{ alignItems: 'flex-start', flexWrap: 'wrap', gap: 10 }}>
        <div style={{ minWidth: 240, flex: 1 }}>
          <div className="row" style={{ gap: 7, marginBottom: 5 }}>
            <span className="kpi-icon" style={{ width: 24, height: 24 }}>
              <IconDoc width={13} height={13} />
            </span>
            <span className="tiny dim mono">{postMortem.id}</span>
            <SeverityBadge severity={postMortem.severity} small />
            <Badge tone={postMortem.status === 'published' ? 'ok' : 'ghost'}>{postMortem.status}</Badge>
          </div>
          <h3 style={{ fontSize: 15, margin: 0, letterSpacing: -0.2 }}>{postMortem.title}</h3>
          <div className="tiny dim" style={{ marginTop: 3 }}>
            {postMortem.generatedBy === 'llm' ? 'LLM + retrieval' : 'PulseReasoner'} · {dt(postMortem.generatedAt)}
            {postMortem.incidentId ? ` · ${postMortem.incidentId}` : ''}
          </div>
        </div>
        <div className="right row" style={{ gap: 7, flexWrap: 'wrap' }}>
          {onRegenerate ? (
            <button
              className="btn btn-sm"
              disabled={busy}
              onClick={async () => {
                setBusy(true);
                try { await onRegenerate(); } finally { setBusy(false); }
              }}
            >
              <IconRefresh width={13} height={13} />
              {busy ? 'Generating…' : 'Regenerate'}
            </button>
          ) : null}
          <button className="btn btn-ghost btn-sm" onClick={() => downloadMarkdown(postMortem)}>
            <IconDownload width={13} height={13} />
            Export .md
          </button>
        </div>
      </header>

      <div className="panel-body">
        {/* ── Quick-glance metrics strip ─────────────────────────────────── */}
        <div className="pm-summary-grid" style={{ marginBottom: 18 }}>
          {[
            { k: 'MTTR', v: postMortem.metrics.mttr },
            { k: 'Blast radius', v: postMortem.metrics.blastRadius },
            { k: 'Error budget', v: postMortem.metrics.errorBudgetBurn },
            { k: 'Customer impact', v: postMortem.metrics.customerImpact },
          ].map((m) => (
            <div key={m.k} className="pm-metric-card">
              <div className="metric-key">{m.k}</div>
              <div className="metric-val">{m.v}</div>
            </div>
          ))}
        </div>

        {/* ── Collapsible report sections ─────────────────────────────────── */}
        <ReportSection num={1} title="Summary" defaultOpen>
          <p className="small muted" style={{ margin: 0, lineHeight: 1.65 }}>{postMortem.summary}</p>
        </ReportSection>

        <ReportSection num={2} title="Impact" defaultOpen={!compact}>
          <p className="small muted" style={{ margin: 0, lineHeight: 1.65 }}>{postMortem.impact}</p>
        </ReportSection>

        <ReportSection num={3} title={`Timeline (${postMortem.timeline.length} events)`} defaultOpen={!compact}>
          <div className="timeline">
            {postMortem.timeline.slice(0, compact ? 5 : 20).map((event, i) => (
              <div className={`timeline-item ${event.kind}`} key={`${event.at}-${i}`}>
                <div className="timeline-time">{event.at.slice(11, 19)}Z</div>
                <div className="timeline-label">{event.label}</div>
                <div className="timeline-detail">{event.detail}</div>
              </div>
            ))}
          </div>
        </ReportSection>

        <ReportSection num={4} title="Root Cause" defaultOpen>
          <p className="small muted" style={{ margin: 0, lineHeight: 1.65 }}>{postMortem.rootCause}</p>
        </ReportSection>

        <ReportSection num={5} title="Resolution" defaultOpen={!compact}>
          <p className="small muted" style={{ margin: 0, lineHeight: 1.65 }}>{postMortem.resolution}</p>
        </ReportSection>

        <ReportSection num={6} title={`Preventive Actions (${postMortem.preventiveActions.length})`} defaultOpen={!compact}>
          <div className="stack" style={{ gap: 6 }}>
            {postMortem.preventiveActions.map((action, i) => (
              <div className="row" key={action} style={{ gap: 8, alignItems: 'flex-start' }}>
                <span
                  className="mono tiny"
                  style={{
                    width: 18, height: 18, borderRadius: 5, display: 'grid', placeItems: 'center',
                    background: 'rgba(6,182,212,.1)', border: '1px solid rgba(6,182,212,.25)', color: '#67e8f9', flex: 'none', fontSize: 10,
                  }}
                >
                  {i + 1}
                </span>
                <span className="small muted">{action}</span>
              </div>
            ))}
          </div>
        </ReportSection>

        <ReportSection num={7} title={`Action Items (${postMortem.actionItems.length})`} defaultOpen={!compact}>
          <div className="scroll-x">
            <table className="table">
              <thead>
                <tr>
                  <th>Task</th>
                  <th>Owner</th>
                  <th>Priority</th>
                </tr>
              </thead>
              <tbody>
                {postMortem.actionItems.map((a) => (
                  <tr key={a.task}>
                    <td className="small" style={{ maxWidth: 340 }}>{a.task}</td>
                    <td className="small muted">{a.owner}</td>
                    <td>
                      <span className={`badge ${a.priority === 'P0' ? 'badge-critical' : a.priority === 'P1' ? 'badge-medium' : 'badge-ghost'}`}>{a.priority}</span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </ReportSection>

        <ReportSection num={8} title={`Lessons Learned (${postMortem.lessonsLearned.length})`} defaultOpen={!compact}>
          <div className="stack" style={{ gap: 6 }}>
            {postMortem.lessonsLearned.map((lesson) => (
              <div className="row" key={lesson} style={{ gap: 8, alignItems: 'flex-start' }}>
                <IconCheck width={13} height={13} style={{ marginTop: 3, color: 'var(--ok)', flex: 'none' }} />
                <span className="small muted">{lesson}</span>
              </div>
            ))}
          </div>
        </ReportSection>

        <div className="divider" />
        <div className="tiny dim" style={{ textAlign: 'center' }}>
          Blameless post-mortem · CodePulse AI Incident Memory
        </div>
      </div>
    </article>
  );
}
